package com.mirigangneung.course.controller;import com.mirigangneung.course.dto.*;import com.mirigangneung.course.service.CourseService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1")public class CourseController{private final CourseService s;public CourseController(CourseService x){s=x;}@PostMapping("/courses")public CourseResponse create(@Valid @RequestBody CreateCourseRequest r){return s.create(r);}@GetMapping("/courses/{id}")public CourseResponse get(@PathVariable String id){return s.get(id);}@DeleteMapping("/courses/{id}")public void delete(@PathVariable String id){s.delete(id);}@PostMapping("/courses/{id}/share")public ShareResponse share(@PathVariable String id){return s.share(id);}@DeleteMapping("/courses/{id}/share")public void revoke(@PathVariable String id){s.revoke(id);}@GetMapping("/share/courses/{token}")public CourseResponse shared(@PathVariable String token){return s.shared(token);}}
